sysevent_script_action.script:
var newimp = event.parm1.toString();
gs.info("user id is " + newimp);

var req_item = new GlideRecord('sc_req_item');
req_item.addQuery('requested_for', newimp);
req_item.query();

while (req_item.next()) {
  //gs.addInfoMessage('Found hardware with asset tag: ' + req_item.asset_tag);
  //gs.addInfoMessage('Hardware name: ' + req_item.name);
  gs.info(req_item.number + ': ' + getVariableResponse(req_item).substring(0,8));
}


var hwAsset = new GlideRecord('alm_hardware');
hwAsset.addQuery('asset_tag', getVariableResponse(req_item).substring(0,8));
hwAsset.query();
while (hwAsset.next()) {
  gs.info('Found hardware with asset tag: ' + hwAsset.asset_tag);
  gs.info('Hardware name: ' + hwAsset.name);
  hwAsset.install_status = '1';
  hwAsset.assigned_to = newimp;
  hwAsset.update();
}

function getVariableResponse(ritmGr) {
    var listPC;
    var scOptionGr = new GlideRecord('sc_item_option_mtom');
    scOptionGr.addEncodedQuery('request_item=' + ritmGr.sys_id);
    scOptionGr.query();
    while(scOptionGr.next()) {
        //list.push('Question: ' + scOptionGr.sc_item_option.item_option_new.getDisplayValue() + '\tQuestion Sys ID: ' + scOptionGr.sc_item_option.item_option_new + '\tValue: ' + scOptionGr.sc_item_option.value);
		var question = scOptionGr.sc_item_option.item_option_new.getDisplayValue();
		if (question != 'what type of computer do you prefer?') {
			continue;
		}
		listPC = scOptionGr.sc_item_option.value;
		break;
    }
    return listPC;
}
